<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class ServiceReviewService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly SiteAssuranceService $assurance,private readonly ?IntegrationCentreService $integrations=null) {}
    private function mapped(array $r):void {$site=$this->access->requireSite($r['site_id']);if((string)$site['client_id']!==(string)$r['client_id']||!$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND user_id=:actor AND client_id=:client',['company'=>$this->company(),'actor'=>$this->actor(),'client'=>$r['client_id']]))throw HttpException::notFound();}
    private function review(string $id,bool $client):array {$r=$this->row('monthly_service_reviews','review_id',$id);$site=$this->access->requireSite($r['site_id']);if((string)$site['client_id']!==(string)$r['client_id'])throw HttpException::notFound();if($client){$this->mapped($r);if($r['state']!=='PUBLISHED')throw HttpException::notFound();}return $r;}
    public function list(array $input,bool $client=false):array {$this->fields($input,['site_id']);$site=$this->access->requireSite($input['site_id']??null);if($client)$this->mapped(['site_id'=>$site['site_id'],'client_id'=>$site['client_id']]);$rows=$this->db->fetchAll('SELECT * FROM monthly_service_reviews WHERE company_id=:company AND site_id=:site AND client_id=:client'.($client?" AND state='PUBLISHED'":'').' ORDER BY month_code DESC LIMIT 100',['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id']]);foreach($rows as&$r){$r['snapshot']=json_decode($r['snapshot_json'],true,512,JSON_THROW_ON_ERROR);unset($r['snapshot_json']);$r['actions']=$this->db->fetchAll('SELECT * FROM service_review_actions WHERE company_id=:company AND review_id=:id ORDER BY action_id',['company'=>$this->company(),'id'=>$r['review_id']]);$r['feedback']=$this->db->fetchAll('SELECT user_id,rating,comments,created_at FROM service_review_feedback WHERE company_id=:company AND review_id=:id ORDER BY feedback_id',['company'=>$this->company(),'id'=>$r['review_id']]);}unset($r);return $rows;}
    public function generate(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','month_code','summary','expected_revision']);$site=$this->access->requireSite($input['site_id']??null);$month=$input['month_code']??null;if(!is_string($month)||!preg_match('/^20[0-9]{2}-(0[1-9]|1[0-2])$/D',$month)||$month>gmdate('Y-m'))throw HttpException::unprocessable('Choose a valid current or previous month.');$from=$month.'-01';$to=min(gmdate('Y-m-d'),(new \DateTimeImmutable($from,new \DateTimeZone('UTC')))->modify('last day of this month')->format('Y-m-d'));$old=$this->db->fetch('SELECT * FROM monthly_service_reviews WHERE company_id=:company AND site_id=:site AND month_code=:month',['company'=>$this->company(),'site'=>$site['site_id'],'month'=>$month]);if(($old&&$old['state']!=='DRAFT')||$this->number($input['expected_revision']??null,0)!==(int)($old['revision']??0))throw HttpException::conflict('Only the current draft can be regenerated.');$params=['company'=>$this->company(),'site'=>$site['site_id'],'start'=>$from.' 00:00:00','end'=>gmdate('Y-m-d H:i:s',strtotime($to.' UTC')+86400)];$recurring=$this->db->fetchAll('SELECT incident_type,COUNT(*) AS total FROM incidents WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND occurred_at>=:start AND occurred_at<:end GROUP BY incident_type HAVING COUNT(*)>1',$params);$snapshot=['service_levels'=>$this->assurance->serviceReport(['site_id'=>$site['site_id'],'date_from'=>$from,'date_to'=>$to]),'recurring_incident_types'=>$recurring,'month_partial'=>$month===gmdate('Y-m'),'generated_at'=>gmdate('Y-m-d H:i:s')];$v=['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id'],'month'=>$month,'summary'=>$this->text($input['summary']??null,10000),'snapshot'=>json_encode($snapshot,JSON_THROW_ON_ERROR),'now'=>gmdate('Y-m-d H:i:s')];if($old){$this->db->execute('UPDATE monthly_service_reviews SET client_id=:client,summary=:summary,snapshot_json=:snapshot,generated_at=:now,revision=revision+1 WHERE company_id=:company AND site_id=:site AND month_code=:month',$v);$id=(string)$old['review_id'];}else{$this->db->execute('INSERT INTO monthly_service_reviews(company_id,site_id,client_id,month_code,summary,snapshot_json,generated_at,created_by_user_id) VALUES(:company,:site,:client,:month,:summary,:snapshot,:now,:actor)',$v+['actor'=>$this->actor()]);$id=(string)$this->db->connection()->lastInsertId();}$this->audit->record('monthly_service_review','draft_generated',$id);return ['id'=>$id];});}
    public function publish(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$r=$this->review($id,false);if($r['state']!=='DRAFT'||$this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Review changed or is already published.');$site=$this->site($r['site_id']);if((string)$site['client_id']!==(string)$r['client_id'])throw HttpException::conflict('The site client changed. Regenerate the draft.');$hash=hash('sha256',$r['snapshot_json'].'|'.$r['summary'].'|'.$r['revision']);$this->db->execute("UPDATE monthly_service_reviews SET state='PUBLISHED',published_at=:now,published_hash=:hash,revision=revision+1 WHERE company_id=:company AND review_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'hash'=>$hash,'company'=>$this->company(),'id'=>$id]);$this->audit->record('monthly_service_review','published',$id);$this->integrations?->event((string)$r['site_id'],'service_review.published',['review_id'=>$id]);return ['published'=>true];});}
    public function action(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['title','owner_user_id','due_on']);$this->review($id,false);$user=$this->row('users','user_id',$input['owner_user_id']??null);if($user['status']!=='ACTIVE')throw HttpException::unprocessable('Choose an active action owner.');$this->db->execute('INSERT INTO service_review_actions(company_id,review_id,title,owner_user_id,due_on) VALUES(:company,:review,:title,:owner,:due)',['company'=>$this->company(),'review'=>$id,'title'=>$this->text($input['title']??null,150),'owner'=>$user['user_id'],'due'=>$this->day($input['due_on']??null)]);return $this->created('service_review_action');});}
    public function finishAction(string $id,array $input,bool $client=false):array {return $this->atomic(function()use($id,$input,$client){$this->fields($input,$client?['expected_revision']:['expected_revision','notes']);$a=$this->row('service_review_actions','action_id',$id);$this->review((string)$a['review_id'],$client);if($this->number($input['expected_revision']??null)!==(int)$a['revision']||$a['state']!==($client?'COMPLETED':'OPEN'))throw HttpException::conflict('Action changed or is not ready for this step.');if($client)$this->db->execute("UPDATE service_review_actions SET state='CLIENT_CONFIRMED',revision=revision+1,confirmed_by_user_id=:actor,confirmed_at=:now WHERE company_id=:company AND action_id=:id",['actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);else $this->db->execute("UPDATE service_review_actions SET state='COMPLETED',revision=revision+1,completion_notes=:notes,completed_at=:now WHERE company_id=:company AND action_id=:id",['notes'=>$this->text($input['notes']??null,2000),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('service_review_action',$client?'client_confirmed':'completed',$id);return ['saved'=>true];});}
    public function feedback(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_hash','rating','comments']);$r=$this->review($id,true);if(!is_string($input['expected_hash']??null)||!hash_equals($r['published_hash'],$input['expected_hash']))throw HttpException::conflict('Read the published review first.');if($this->db->fetch('SELECT feedback_id FROM service_review_feedback WHERE company_id=:company AND review_id=:id AND user_id=:actor',['company'=>$this->company(),'id'=>$id,'actor'=>$this->actor()]))throw HttpException::conflict('You already submitted feedback for this review.');$this->db->execute('INSERT INTO service_review_feedback(company_id,review_id,user_id,rating,comments,review_hash,created_at) VALUES(:company,:review,:actor,:rating,:comments,:hash,:now)',['company'=>$this->company(),'review'=>$id,'actor'=>$this->actor(),'rating'=>$this->number($input['rating']??null,1,5),'comments'=>$this->text($input['comments']??null,2000),'hash'=>$r['published_hash'],'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('service_review_feedback');});}
}
